<script setup>
import {computed,ref,watch,nextTick,onBeforeUnmount,onMounted} from 'vue'
import {VueFlow,Handle,Position,MarkerType} from '@vue-flow/core'
import {Background} from '@vue-flow/background'
import {Controls} from '@vue-flow/controls'
import {MiniMap} from '@vue-flow/minimap'
import {Phone,Users,MessageCircle,Check,Clock,Settings2,GitBranch,Pause,Save,Maximize2,LayoutGrid,PanelRightClose,PanelRightOpen,Move,ArrowRight} from 'lucide-vue-next'
import VoiceJourneyNodeEditor from './VoiceJourneyNodeEditor.vue'
const props=defineProps({journey:Object,campaign:Object,contacts:Array,queues:Array,lists:Array,senders:Array,templates:Array,qrTemplates:Array,references:Array,canManage:Boolean})
const emit=defineEmits(['configure','navigate','saved'])
const editor=ref(null)
const step=ref('voice'),panel=ref(true),nodeDirty=ref(false),editorSaving=ref(false),saving=ref(false),error=ref(''),notice=ref(''),pending=ref(null)
const layoutRevision=ref(props.journey.layout?.revision||0)
const defaults={entry:{x:290,y:20},voice:{x:290,y:205},decision:{x:290,y:425},wait:{x:650,y:255},exit:{x:-30,y:670},message:{x:650,y:670}}
const meta={entry:{title:'Público da jornada',caption:'01 · ENTRADA',icon:Users,color:'blue'},voice:{title:'Ligar para o cliente',caption:'02 · VOZ',icon:Phone,color:'gold'},decision:{title:'O cliente atendeu?',caption:'03 · RESULTADO',icon:GitBranch,color:'blue'},wait:{title:'Aguardar e tentar novamente',caption:'INTERVALO',icon:Clock,color:'neutral'},message:{title:'Enviar WhatsApp',caption:'04 · MENSAGEM',icon:MessageCircle,color:'gold'},exit:{title:'Encerrar abordagem',caption:'SAÍDA · ATENDEU',icon:Check,color:'green'}}
const nodes=ref(Object.entries(defaults).map(([id,position])=>({id,type:'voiceStage',position:props.journey.layout?.positions?.find(p=>p.id===id)||position,data:{},deletable:false,connectable:false})))
const savedLayout=ref(positions())
const layoutSignature=value=>JSON.stringify([...value].sort((a,b)=>a.id.localeCompare(b.id)).map(p=>({id:p.id,x:Math.round(p.x),y:Math.round(p.y)})))
const layoutDirty=computed(()=>layoutSignature(positions())!==layoutSignature(savedLayout.value))
const pendingMessage=computed(()=>nodeDirty.value?(pending.value?.scope==='all'&&layoutDirty.value?'Há alterações não salvas na etapa e nas posições do mapa.':'Há alterações não salvas na etapa “'+meta[step.value].title+'”.'):'Há posições não salvas no mapa. Use “Salvar posições” para mantê-las.')
watch([nodeDirty,layoutDirty],()=>{if(pending.value&&!nodeDirty.value&&(pending.value.scope==='node'||!layoutDirty.value))pending.value=null})
function nodeSaved(journey){nodeDirty.value=false;if(pending.value?.scope==='node')pending.value=null;emit('saved',journey)}
let flow,resizeObserver
const region=ref(null)
const s=computed(()=>props.journey.settings)
const interval=computed(()=>props.journey.retry_minutes?.no_answer??s.value.retry_minutes)
const edges=computed(()=>[
 edge('entry-voice','entry','voice','Horário e autorização','bottom','top'),
 edge('voice-decision','voice','decision','Após cada tentativa','bottom','top'),
 edge('decision-exit','decision','exit','Sim · encerra a jornada','left','top','#448765'),
 edge('decision-message','decision','message',s.value.whatsapp_enabled?'Não · '+s.value.whatsapp_after+' não atendimentos':'WhatsApp desativado','bottom','top',s.value.whatsapp_enabled?'#b88c31':'#a6aaa2'),
 edge('decision-wait','decision','wait','Não · antes do limite','right','bottom','#6385b8'),
 edge('wait-voice','wait','voice',interval.value+' minutos','left','right','#6385b8'),
])
function edge(id,source,target,label,sourceHandle,targetHandle,color='#a9ada3'){return {id,source,target,label,sourceHandle,targetHandle,type:'smoothstep',deletable:false,updatable:false,selectable:false,style:{stroke:color,strokeWidth:1.6},markerEnd:{type:MarkerType.ArrowClosed,color},labelStyle:{fill:color,fontSize:11,fontWeight:600},labelBgStyle:{fill:'#f8f8f4',fillOpacity:1},labelBgPadding:[8,6],labelBgBorderRadius:5}}
const status=computed(()=>({paused:'Pausada',draft:'Rascunho',testing:'Habilitada',completed:'Concluída',cancelled:'Cancelada'})[props.journey.status])
function fit(){nextTick(()=>flow?.fitView({padding:.16,duration:250,maxZoom:1}))}
function requestLeave(fn){if(editorSaving.value||saving.value){notice.value='Aguarde a conclusão do salvamento.';return}if(nodeDirty.value||layoutDirty.value){pending.value={run:fn,scope:'all'};return}pending.value=null;fn()}
defineExpose({requestLeave})
function action(fn){if(editorSaving.value||saving.value){notice.value='Aguarde a conclusão do salvamento.';return}if(nodeDirty.value){pending.value={run:fn,scope:'node'};return}pending.value=null;fn()}
function select(id){if(id===step.value){panel.value=true;return}action(()=>{step.value=id;panel.value=true;error.value='';notice.value=''})}
function discardAndContinue(){const next=pending.value;pending.value=null;editor.value?.reset();nodeDirty.value=false;if(next?.scope==='all'&&layoutDirty.value)nodes.value=nodes.value.map(n=>({...n,position:{...savedLayout.value.find(p=>p.id===n.id)}}));next?.run()}
function navigate(section){action(()=>emit('navigate',section))}
function positions(){return nodes.value.map(n=>({id:n.id,x:Math.round(n.position.x),y:Math.round(n.position.y)}))}
function organize(){nodes.value=nodes.value.map(n=>({...n,position:{...defaults[n.id]}}));fit()}
async function saveLayout(){if(saving.value)return;const submitted=positions();saving.value=true;error.value='';try{const r=await fetch('/api/voice/journeys/'+props.journey.id+'/layout',{method:'PUT',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({revision:layoutRevision.value,positions:submitted})});const d=await r.json();if(!r.ok)throw new Error(d.message);layoutRevision.value=d.revision;savedLayout.value=d.positions||submitted;notice.value='Posições salvas. As regras da jornada foram preservadas.'}catch(e){error.value=e.message}finally{saving.value=false}}
function beforeUnload(e){if(nodeDirty.value||layoutDirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);resizeObserver=new ResizeObserver(fit);if(region.value)resizeObserver.observe(region.value)});onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeUnload);resizeObserver?.disconnect()})
watch(panel,()=>fit())
</script>
<template><section class="voice-journey vj-builder"><header class="vj-heading"><div><span class="eyebrow">CONSTRUTOR DE CADÊNCIA</span><h2>{{journey.name}}</h2><p>Clique nos cartões para configurar. Arraste para organizar sua jornada.</p></div><span :class="['status',journey.status==='testing'?'active':'paused']">{{status}}</span><button class="secondary" @click="action(()=>emit('configure'))"><Settings2 :size="15"/>Configuração geral</button></header>
<div class="vj-summary"><span><Users :size="14"/>{{journey.contact_count}} contatos</span><span v-if="s.reentry" class="vj-card-tag">{{({once:"Participação única",segment_return:"Reentrada ao retornar",interval:"Reentrada após "+s.reentry.interval_days+" dias",event:"Entrada por evento"})[s.reentry.mode]}}</span><span><Phone :size="14"/>Até {{s.max_attempts}} tentativas{{s.reentry?" por participação":""}}</span><span><Clock :size="14"/>{{interval}} min entre tentativas</span><span><MessageCircle :size="14"/>{{s.whatsapp_enabled?'WhatsApp após '+s.whatsapp_after+' não atendimentos':'WhatsApp desativado'}}</span></div>
<div class="vj-toolbar"><div><Move :size="15"/><span>{{layoutDirty?'Posições não salvas':'Arraste os cartões · use o zoom para navegar'}}</span></div><div><button class="secondary" aria-label="Enquadrar jornada" title="Enquadrar jornada" @click="fit"><Maximize2 :size="16"/></button><button class="secondary" :disabled="!canManage||saving||editorSaving" @click="organize"><LayoutGrid :size="15"/><span>Organizar</span></button><button class="secondary" :aria-label="panel?'Ocultar painel':'Mostrar painel'" @click="panel=!panel"><PanelRightClose v-if="panel" :size="17"/><PanelRightOpen v-else :size="17"/></button><button class="primary" :disabled="!layoutDirty||saving||!canManage" @click="saveLayout"><Save :size="15"/>{{saving?'Salvando…':'Salvar posições'}}</button></div></div>
<div v-if="pending" class="vj-unsaved" role="alert"><span>{{pendingMessage}}</span><button class="secondary" @click="pending=null">Continuar editando</button><button class="primary" @click="discardAndContinue">Descartar e continuar</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="vj-feedback" role="status">{{notice}}</p>
<div :class="['vj-workbench',{'panel-hidden':!panel}]"><div ref="region" class="vj-flow-region"><nav class="vj-stage-nav" aria-label="Etapas da jornada"><button v-for="(m,id) in meta" :key="id" :class="{active:step===id}" :aria-label="'Configurar '+m.title" :title="m.title" @click="select(id)"><component :is="m.icon" :size="18"/></button></nav>
<VueFlow :id="'voice-journey-'+journey.id" v-model:nodes="nodes" :edges="edges" :nodes-draggable="canManage&&!saving&&!editorSaving" :nodes-connectable="false" :edges-updatable="false" :delete-key-code="null" :min-zoom=".25" :max-zoom="1.6" :node-extent="[[-5000,-5000],[5000,5000]]" :zoom-on-double-click="false" :pan-on-scroll="false" :prevent-scrolling="false" @nodes-initialized="fit" @init="instance=>{flow=instance;fit()}" >
<Background :gap="22" :size="1" pattern-color="#cdd2c7"/><Controls :show-interactive="false"/><MiniMap :width="118" :height="82" pannable zoomable :node-color="n=>({entry:'#dbe5ff',voice:'#e7cf95',decision:'#dbe5ff',wait:'#e1e3dc',exit:'#c4e5ce',message:'#e7cf95'})[n.id]"/>
<template #node-voiceStage="{id}"><div :class="['vj-flow-card',meta[id].color,{chosen:step===id}]" :data-stage="id"><Handle v-for="[key,pos] in [['top',Position.Top],['right',Position.Right],['bottom',Position.Bottom],['left',Position.Left]]" :key="key" :id="key" type="source" :position="pos" :connectable="false"/><Handle v-for="[key,pos] in [['top',Position.Top],['right',Position.Right],['bottom',Position.Bottom],['left',Position.Left]]" :key="'target-'+key" :id="key" type="target" :position="pos" :connectable="false"/>
<button type="button" :aria-label="'Editar cartão: '+meta[id].title" @click="select(id)"><span class="vj-card-top"><span class="vj-card-icon"><component :is="meta[id].icon" :size="20"/></span><small>{{meta[id].caption}}</small><Settings2 v-if="id!=='exit'" :size="14"/><Check v-else :size="15"/></span><strong>{{meta[id].title}}</strong><template v-if="id==='entry'"><p>{{journey.list?.name||'Contatos escolhidos na campanha'}}</p><span class="vj-card-tag">{{journey.contact_count}} contatos</span><span v-if="s.reentry" class="vj-card-tag">{{({once:"Participação única",segment_return:"Reentrada ao retornar",interval:"Reentrada após "+s.reentry.interval_days+" dias",event:"Entrada por evento"})[s.reentry.mode]}}</span></template><template v-else-if="id==='voice'"><p>{{s.mode==='progressive'?'Discagem progressiva':'Seleção pelo atendente'}} · {{s.start_time}}–{{s.end_time}}</p><span class="vj-card-tag">Até {{s.max_attempts}} tentativas{{s.reentry?" por participação":""}}</span><span class="vj-card-tag">{{s.days.length}} dias / semana</span></template><template v-else-if="id==='decision'"><p>Atendeu: encerra. Não atendeu: verifica o limite.</p><span class="vj-card-tag">WhatsApp após {{s.whatsapp_after}}</span></template><template v-else-if="id==='wait'"><p>Aguarda a próxima janela e retorna à ligação.</p><span class="vj-card-tag">{{interval}} minutos</span></template><template v-else-if="id==='message'"><p>{{journey.sender?.provider==='qr'?'WhatsApp por QR Code':'API oficial Twilio'}} · {{journey.sender?.number||'remetente pendente'}}</p><span class="vj-card-tag">{{s.whatsapp_enabled?'Mensagem personalizada':'Desativado'}}</span></template><template v-else><p>Finaliza as tentativas e cancela a mensagem pendente.</p><span class="vj-card-tag">Regra de encerramento</span></template></button></div></template>
</VueFlow><div class="vj-canvas-caption">6 cartões · conexões vinculadas às regras do discador</div></div>
<VoiceJourneyNodeEditor ref="editor" v-show="panel" :key="step" :node="step" :journey="journey" :campaign="campaign" :contacts="contacts" :queues="queues" :lists="lists" :senders="senders" :templates="templates" :qr-templates="qrTemplates" :references="references" :can-manage="canManage" @saved="nodeSaved" @navigate="navigate" @dirty="nodeDirty=$event" @saving="editorSaving=$event"/></div>
<footer class="vj-readiness"><Pause :size="17"/><p><strong>{{status}}.</strong> {{journey.status==='testing'?'A fila e o atendente controlam o início das chamadas.':'Selecione o público e conclua a conexão do WhatsApp antes de ativar.'}} Editar cartões ou mover o mapa não inicia chamadas nem envia mensagens.</p></footer></section></template>
<style scoped>
