olid #3e67c7}.vj-card-top{display:flex;gap:9px;align-items:center;margin-bottom:12px}.vj-card-top small{flex:1;font-size:9px;font-weight:700;letter-spacing:.7px;color:#7d8675}.vj-card-top>svg{color:#9ba391}.vj-card-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#f1f2ed;color:#738066}.vj-flow-card.gold .vj-card-icon{background:#faf1da;color:#ad7e29}.vj-flow-card.blue .vj-card-icon{background:#edf1ff;color:#3e67c7}.vj-flow-card.green .vj-card-icon{background:#e8f5ec;color:#428961}.vj-flow-card strong{font-size:14px;line-height:1.35;display:block;font-weight:700}.vj-flow-card p{font-size:11px;line-height:1.6;margin:7px 0 11px;color:#7b8373;overflow-wrap:anywhere}.vj-card-tag{font-size:9px;display:inline-block;padding:5px 7px;background:#f5f6f0;color:#727a65;border:1px solid #e8ebdf;border-radius:5px;margin-right:4px;margin-top:3px}.vj-canvas-caption{position:absolute;bottom:15px;left:80px;right:145px;pointer-events:none;font-size:9px;color:#89917e;text-align:center;background:#f6f7f2dd;padding:7px;border-radius:6px}.vj-flow-region :deep(.vue-flow__handle){width:7px;height:7px;border:2px solid white;background:#a7b099;pointer-events:none}.vj-flow-region :deep(.vue-flow__minimap){width:118px;height:82px;border:1px solid #e0e3d7;border-radius:8px;overflow:hidden;box-shadow:0 3px 15px #1a301309}.vj-flow-region :deep(.vue-flow__controls){box-shadow:0 3px 12px #1a301309;border:1px solid #e0e3d7;border-radius:8px;overflow:hidden}.vj-flow-region :deep(.vue-flow__controls-button){background:white;border-color:#ebede5}.vj-readiness{display:flex;gap:12px;align-items:flex-start;background:#faf5e8;border:1px solid #ede0bf;border-radius:12px;padding:16px 20px;margin-top:18px;color:#927235}.vj-readiness p{font-size:11px;line-height:1.7;margin:0}.vj-readiness svg{flex-shrink:0;margin-top:2px}.vj-unsaved{display:flex;align-items:center;gap:10px;padding:12px;background:#fff2d3;font-size:12px;flex-wrap:wrap}.vj-unsaved button{font-size:11px}.vj-feedback{font-size:12px;color:#3c7955;padding:10px}.vj-toolbar button:disabled{opacity:.45}@media(min-width:1650px){.vj-workbench{grid-template-columns:minmax(0,1fr) 410px;height:800px}}@media(max-width:1050px){.vj-workbench{height:auto;grid-template-columns:1fr}.vj-flow-region{height:620px}.vj-node-editor{max-height:650px;border-left:0!important;border-top:1px solid #dfe2d8}.vj-toolbar>div:first-child{display:none}.vj-toolbar{justify-content:flex-end}.vj-heading h2{font-size:21px}}@media(max-width:620px){.vj-heading>div{min-width:0;flex-basis:100%}.vj-heading h2{font-size:20px}.vj-flow-region{height:540px}.vj-summary{gap:12px}.vj-toolbar{padding:9px;gap:4px}.vj-toolbar button{padding:9px;font-size:10px}.vj-toolbar>div{gap:4px}.vj-toolbar button>span{display:none}.vj-stage-nav{left:8px;top:8px;padding:4px}.vj-stage-nav button{padding:7px}.vj-canvas-caption{display:none}.vj-node-editor{max-height:none}.vj-workbench{border-radius:0 0 12px 12px}.vj-readiness{padding:12px}.vj-readiness p{font-size:10px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
